//! Integration tests for the libmpv backend, through the `Player` facade:
//! starting under a non-C locale, real playback and rendering in GtkGLArea,
//! falling back to the next URL, per-channel HTTP headers, pause and stop.
//!
//! They need a display (X11 or Wayland; Xvfb / headless Weston with software
//! OpenGL work too). The video sources are generated by mpv (lavfi) and the
//! HTTP server is local, so no internet is needed.
//!
//! ```sh
//! xvfb-run -a cargo test -p tvmaxe --test player
//! cargo test -p tvmaxe --test player -- headers   # only tests whose name contains "headers"
//! ```

#[macro_use]
mod common;

use common::{DEAD_URL, TEST_AUDIO, TEST_VIDEO, TestResult, sleep, wait_until};
use gtk::prelude::*;
use std::cell::RefCell;
use std::io::{Read, Write};
use std::net::TcpListener;
use std::rc::Rc;
use std::sync::mpsc;
use std::time::Duration;
use tvmaxe::player::{PlaybackSettings, Player, PlayerEvent, StreamOptions};

const START_TIMEOUT: Duration = Duration::from_secs(20);

fn main() {
    common::run(
        "player (libmpv)",
        &[
            ("starts_under_non_c_locale", || {
                Box::pin(starts_under_non_c_locale())
            }),
            ("plays_and_renders_video", || {
                Box::pin(plays_and_renders_video())
            }),
            ("falls_back_to_next_url", || {
                Box::pin(falls_back_to_next_url())
            }),
            ("fails_when_all_urls_fail", || {
                Box::pin(fails_when_all_urls_fail())
            }),
            ("per_channel_http_headers", || {
                Box::pin(sends_channel_http_headers())
            }),
            ("pause_and_stop", || Box::pin(pause_and_stop())),
            ("switch_away_from_dead_url", || {
                Box::pin(switch_away_from_dead_url())
            }),
            ("plays_audio_only_radio", || {
                Box::pin(plays_audio_only_radio())
            }),
            ("audio_tracks", || Box::pin(audio_tracks())),
        ],
    );
}

/// A window with the video area and the recorded player events.
struct Rig {
    window: gtk::Window,
    player: Rc<Player>,
    events: Rc<RefCell<Vec<PlayerEvent>>>,
}

impl Rig {
    async fn new() -> Result<Self, String> {
        let player = Player::new().map_err(|e| format!("Player::new: {e:#}"))?;
        let events: Rc<RefCell<Vec<PlayerEvent>>> = Rc::default();
        let e = events.clone();
        player.connect_event(move |ev| e.borrow_mut().push(ev));
        let window = gtk::Window::builder()
            .title("tvmaxe test")
            .default_width(320)
            .default_height(240)
            .child(&player.widget())
            .build();
        window.present();
        let w = player.widget();
        wait_until("video area shown", START_TIMEOUT, || w.is_mapped()).await?;
        Ok(Self {
            window,
            player,
            events,
        })
    }

    fn has(&self, f: impl Fn(&PlayerEvent) -> bool) -> bool {
        self.events.borrow().iter().any(f)
    }

    async fn wait_playing(&self) -> TestResult {
        wait_until("PlayerEvent::Playing", START_TIMEOUT, || {
            self.has(|e| *e == PlayerEvent::Playing)
                || self.has(|e| matches!(e, PlayerEvent::Failed(_)))
        })
        .await?;
        if let Some(PlayerEvent::Failed(m)) = self
            .events
            .borrow()
            .iter()
            .find(|e| matches!(e, PlayerEvent::Failed(_)))
        {
            return Err(format!("playback failed: {m}"));
        }
        Ok(())
    }

    async fn wait_failed(&self) -> TestResult {
        wait_until("PlayerEvent::Failed", START_TIMEOUT, || {
            self.has(|e| matches!(e, PlayerEvent::Failed(_)))
        })
        .await
    }
}

impl Drop for Rig {
    fn drop(&mut self) {
        self.player.stop();
        self.window.destroy();
    }
}

fn urls(v: &[&str]) -> Vec<String> {
    v.iter().map(|s| s.to_string()).collect()
}

/// A real bug: GTK applies the system LC_NUMERIC (ro_RO → "1,5"), and libmpv
/// refuses to start ("Non-C locale detected").
async fn starts_under_non_c_locale() -> TestResult {
    let candidates = [
        c"ro_RO.UTF-8",
        c"ro_RO.utf8",
        c"de_DE.UTF-8",
        c"fr_FR.UTF-8",
        c"en_US.UTF-8",
    ];
    // SAFETY: main thread; no other thread reads the locale now.
    let chosen = candidates
        .iter()
        .find(|l| unsafe { !libc::setlocale(libc::LC_NUMERIC, l.as_ptr()).is_null() });
    let Some(chosen) = chosen else {
        println!("    (no non-C locale installed; only checking startup)");
        return Player::new().map(|_| ()).map_err(|e| format!("{e:#}"));
    };
    let player = Player::new();
    // SAFETY: as above; the returned pointer is read immediately.
    let now = unsafe {
        std::ffi::CStr::from_ptr(libc::setlocale(libc::LC_NUMERIC, std::ptr::null()))
            .to_string_lossy()
            .into_owned()
    };
    check!(
        player.is_ok(),
        "libmpv does not start under LC_NUMERIC={chosen:?}: {:#}",
        player.err().unwrap()
    );
    check!(now == "C", "LC_NUMERIC is still {now:?}, expected \"C\"");
    Ok(())
}

/// Real playback: the Playing event, the time advances, and the colour bars
/// appear in the GtkGLArea (catches "black picture" regressions).
async fn plays_and_renders_video() -> TestResult {
    let rig = Rig::new().await?;
    rig.player
        .play(urls(&[TEST_VIDEO]), StreamOptions::default());
    rig.wait_playing().await?;
    check!(rig.player.is_active(), "player not active after Playing");
    wait_until("playback time advances", START_TIMEOUT, || {
        rig.player.playback_time().is_some_and(|t| t > 0.5)
    })
    .await?;

    let area = rig.player.widget();
    let mut colors = 0;
    for _ in 0..40 {
        colors = distinct_colors(&area)?;
        if colors >= 5 {
            return Ok(());
        }
        sleep(250).await;
    }
    Err(format!(
        "the video area shows {colors} distinct colours, expected the SMPTE bars (≥ 5)"
    ))
}

/// A capture of the video area (exactly what GTK draws) and the number of distinct
/// non-black colours, coarsely rounded so scaling does not matter.
fn distinct_colors(widget: &gtk::Widget) -> Result<usize, String> {
    let (w, h) = (widget.width(), widget.height());
    if w == 0 || h == 0 {
        return Ok(0);
    }
    let parent = widget.parent().ok_or("the video area has no parent")?;
    let snapshot = gtk::Snapshot::new();
    parent.snapshot_child(widget, &snapshot);
    let Some(node) = snapshot.to_node() else {
        return Ok(0);
    };
    let renderer = widget
        .native()
        .and_then(|n| n.renderer())
        .ok_or("the window has no renderer")?;
    let texture = renderer.render_texture(&node, None);
    // Debugging (and a CI artifact): TVMAXE_TEST_CAPTURE=/tmp/capture.png
    if let Some(path) = std::env::var_os("TVMAXE_TEST_CAPTURE") {
        let _ = texture.save_to_png(path);
    }
    let (tw, th) = (texture.width() as usize, texture.height() as usize);
    let mut buf = vec![0u8; tw * th * 4];
    texture.download(&mut buf, tw * 4);
    let mut seen = std::collections::HashSet::new();
    // GDK_MEMORY_DEFAULT = B8G8R8A8 premultiplicat.
    for &[b, g, r, _] in buf.as_chunks::<4>().0 {
        if u16::from(r) + u16::from(g) + u16::from(b) > 60 {
            seen.insert((r >> 6, g >> 6, b >> 6));
        }
    }
    Ok(seen.len())
}

async fn falls_back_to_next_url() -> TestResult {
    let rig = Rig::new().await?;
    rig.player
        .play(urls(&[DEAD_URL, TEST_VIDEO]), StreamOptions::default());
    rig.wait_playing().await?;
    check!(
        !rig.has(|e| matches!(e, PlayerEvent::Failed(_))),
        "URL-ul mort a ajuns la utilizator ca eroare: {:?}",
        rig.events.borrow()
    );
    Ok(())
}

/// Fast zapping: the late error of a dead URL that was already replaced must
/// not fail the channel that replaced it.
async fn switch_away_from_dead_url() -> TestResult {
    let rig = Rig::new().await?;
    // Several delays, so the error arrives before and after the switch.
    for delay in [0, 30, 60, 120] {
        rig.player.play(urls(&[DEAD_URL]), StreamOptions::default());
        sleep(delay).await;
        // A failure before the switch is the dead channel's own.
        rig.events.borrow_mut().clear();
        rig.player
            .play(urls(&[TEST_VIDEO]), StreamOptions::default());
        rig.wait_playing()
            .await
            .map_err(|e| format!("after {delay} ms: {e}"))?;
        sleep(300).await;
        check!(
            !rig.has(|e| matches!(e, PlayerEvent::Failed(_))),
            "after {delay} ms: the dead URL failed the new channel"
        );
        check!(rig.player.is_active(), "after {delay} ms: player stopped");
    }
    Ok(())
}

async fn fails_when_all_urls_fail() -> TestResult {
    let rig = Rig::new().await?;
    rig.player.play(
        urls(&[DEAD_URL, "http://127.0.0.1:9/alt-mort.ts"]),
        StreamOptions::default(),
    );
    rig.wait_failed().await?;
    check!(!rig.player.is_active(), "player still active after failure");
    Ok(())
}

/// Minimal HTTP server: sends back the headers of every request and answers 404.
fn header_server() -> (String, mpsc::Receiver<String>) {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let url = format!("http://{}/live.m3u8", listener.local_addr().unwrap());
    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut s) = stream else { continue };
            let _ = s.set_read_timeout(Some(Duration::from_secs(5)));
            let mut req = Vec::new();
            let mut buf = [0u8; 1024];
            while !req.windows(4).any(|w| w == b"\r\n\r\n") {
                match s.read(&mut buf) {
                    Ok(0) | Err(_) => break,
                    Ok(n) => req.extend_from_slice(&buf[..n]),
                }
            }
            let _ = tx.send(String::from_utf8_lossy(&req).into_owned());
            let _ = s.write_all(
                b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
            );
        }
    });
    (url, rx)
}

async fn next_request(rx: &mpsc::Receiver<String>) -> Result<String, String> {
    let got: RefCell<Option<String>> = RefCell::default();
    wait_until("mpv's HTTP request", START_TIMEOUT, || {
        if got.borrow().is_none() {
            *got.borrow_mut() = rx.try_recv().ok();
        }
        got.borrow().is_some()
    })
    .await?;
    Ok(got.into_inner().unwrap())
}

fn header<'a>(request: &'a str, name: &str) -> Option<&'a str> {
    request.lines().find_map(|l| {
        let (k, v) = l.split_once(':')?;
        k.trim().eq_ignore_ascii_case(name).then(|| v.trim())
    })
}

/// `http-referrer` / `http-user-agent` from M3U reach the server; a channel without
/// them sends no Referer at all (not even empty) and uses the Preferences User-Agent.
async fn sends_channel_http_headers() -> TestResult {
    let (url, rx) = header_server();
    let rig = Rig::new().await?;

    rig.player.play(
        urls(&[&url]),
        StreamOptions {
            referrer: Some("https://referer.example/".into()),
            user_agent: Some("UA-Canal/1.0".into()),
        },
    );
    let req = next_request(&rx).await?;
    check!(
        header(&req, "Referer") == Some("https://referer.example/"),
        "wrong Referer in:\n{req}"
    );
    check!(
        header(&req, "User-Agent") == Some("UA-Canal/1.0"),
        "wrong User-Agent in:\n{req}"
    );
    rig.wait_failed().await?;
    while rx.try_recv().is_ok() {}

    rig.player.apply_settings(&PlaybackSettings {
        user_agent: Some("UA-Preferinte/2.0".into()),
        ..Default::default()
    });
    rig.events.borrow_mut().clear();
    rig.player.play(urls(&[&url]), StreamOptions::default());
    let req = next_request(&rx).await?;
    check!(
        header(&req, "Referer").is_none(),
        "Referer sent for a channel that does not need it:\n{req}"
    );
    check!(
        header(&req, "User-Agent") == Some("UA-Preferinte/2.0"),
        "the Preferences User-Agent is not used:\n{req}"
    );
    rig.wait_failed().await
}

async fn pause_and_stop() -> TestResult {
    let rig = Rig::new().await?;
    rig.player
        .play(urls(&[TEST_VIDEO]), StreamOptions::default());
    rig.wait_playing().await?;

    rig.player.toggle_pause();
    check!(rig.player.is_paused(), "not paused");
    sleep(300).await;
    let t1 = rig.player.playback_time().unwrap_or(0.0);
    sleep(700).await;
    let t2 = rig.player.playback_time().unwrap_or(0.0);
    check!(
        (t2 - t1).abs() < 0.2,
        "time advances while paused: {t1} → {t2}"
    );

    rig.player.toggle_pause();
    check!(!rig.player.is_paused(), "pause was not undone");
    rig.player.stop();
    check!(!rig.player.is_active(), "active after Stop");
    check!(
        rig.events.borrow().last() == Some(&PlayerEvent::Stopped),
        "last event is not Stopped: {:?}",
        rig.events.borrow()
    );
    check!(
        rig.player.playback_time().is_none(),
        "playback time after Stop"
    );
    Ok(())
}

/// Radio (audio only) plays even without a sound card: mpv falls back to a
/// silent output instead of failing.
async fn plays_audio_only_radio() -> TestResult {
    let rig = Rig::new().await?;
    rig.player
        .play(urls(&[TEST_AUDIO]), StreamOptions::default());
    rig.wait_playing().await?;
    wait_until("radio time advances", START_TIMEOUT, || {
        rig.player.playback_time().is_some_and(|t| t > 0.5)
    })
    .await
}

/// The audio tracks are listed, the preferred language is chosen first, and
/// another track can be selected.
async fn audio_tracks() -> TestResult {
    let dir = common::TempDir::new("audio");
    let Some(src) = common::ts_source_two_audio(&dir.0) else {
        return Ok(());
    };
    let rig = Rig::new().await?;
    rig.player.apply_settings(&PlaybackSettings {
        audio_languages: "ro".into(),
        ..Default::default()
    });
    rig.player
        .play(urls(&[src.to_str().unwrap()]), StreamOptions::default());
    rig.wait_playing().await?;
    let selected_lang = || {
        rig.player
            .audio_tracks()
            .into_iter()
            .find(|t| t.selected)
            .and_then(|t| t.lang)
    };
    wait_until("two audio tracks, Romanian selected", START_TIMEOUT, || {
        rig.player.audio_tracks().len() == 2 && selected_lang().as_deref() == Some("ron")
    })
    .await
    .map_err(|e| format!("{e}; tracks {:?}", rig.player.audio_tracks()))?;
    let tracks = rig.player.audio_tracks();
    let ron = tracks
        .iter()
        .find(|t| t.lang.as_deref() == Some("ron"))
        .unwrap();
    check!(ron.channels == Some(6), "channels: {:?}", ron.channels);
    let eng = tracks
        .iter()
        .find(|t| t.lang.as_deref() == Some("eng"))
        .unwrap();
    rig.player.set_audio_track(eng.id);
    wait_until("English selected", START_TIMEOUT, || {
        selected_lang().as_deref() == Some("eng")
    })
    .await
}
